CUSTOM_CSS:
/* Discord Gruvbox-Material Theme */

:root {
  --gruvbox-bg0: #282828;
  --gruvbox-bg1: #32302f;
  --gruvbox-bg2: #45403d;
  --gruvbox-fg0: #d4be98;
  --gruvbox-aqua: #89b482;
}

body {
  background-color: var(--gruvbox-bg0) !important;
  color: var(--gruvbox-fg0) !important;
}

/* Main content area */
.theme-dark {
  background-color: var(--gruvbox-bg0);
  color: var(--gruvbox-fg0);
}

/* Sidebars and panels */
[class*='sidebar'] {
  background-color: var(--gruvbox-bg1) !important;
}

/* Chat messages */
[class*='message'] {
  color: var(--gruvbox-fg0) !important;
}

[class*='mentioned'] {
  background-color: var(--gruvbox-bg2) !important;
}

/* Buttons */
button {
  background-color: var(--gruvbox-bg2) !important;
  color: var(--gruvbox-fg0) !important;
}

button:hover {
  background-color: var(--gruvbox-aqua) !important;
  color: var(--gruvbox-bg0) !important;
}
